{
  "AWSTemplateFormatVersion": "2010-09-09",
  "Description": "Simple Amazon SageMaker Setup",
  "Resources": {
    "SageMakerRole": {
      "Type": "AWS::IAM::Role",
      "Properties": {
        "AssumeRolePolicyDocument": {
          "Version": "2012-10-17",
          "Statement": [
            {
              "Effect": "Allow",
              "Principal": {
                "Service": "sagemaker.amazonaws.com"
              },
              "Action": "sts:AssumeRole"
            }
          ]
        },
        "Policies": [
          {
            "PolicyName": "SageMakerPolicy",
            "PolicyDocument": {
              "Version": "2012-10-17",
              "Statement": [
                {
                  "Effect": "Allow",
                  "Action": [
                    "s3:ListBucket",
                    "s3:PutObject",
                    "s3:GetObject"
                  ],
                  "Resource": "*"
                }
              ]
            }
          }
        ]
      }
    },
    "SageMakerNotebookInstance": {
      "Type": "AWS::SageMaker::NotebookInstance",
      "Properties": {
        "NotebookInstanceName": "MySageMakerNotebook",
        "InstanceType": "ml.t2.medium",
        "RoleArn": { "Fn::GetAtt": ["SageMakerRole", "Arn"] },
        "Tags": [
          {
            "Key": "Name",
            "Value": "MySageMakerNotebook"
          }
        ]
      }
    }
  }
}

{
  "Resources": {
    "ECSCluster": {
      "Type": "AWS::ECS::Cluster",
      "Properties": {
        "ClusterName": "MyCluster",
        "ClusterSettings": [
          {
              "Name": "containerInsights",
              "Value": "disabled"
          }
        ],
        "Tags": [
          {
              "Key": "environment",
              "Value": "production"
          }
        ]
      }
    }
  }
}

{
  "Resources": {
    "SuperCoolAPI": {
      "Properties": {
        "AuthenticationType": "AWS_IAM",
        "IntrospectionConfig": "DISABLED",
        "LogConfig": {
          "CloudWatchLogsRoleArn": {
            "Fn::GetAtt": [
              "SuperCoolAPICloudWatchRole",
              "Arn"
            ]
          },
          "FieldLogLevel": "ALL"
        },
        "Name": "SuperCoolAPI",
        "OwnerContact": "blah-blah",
        "QueryDepthLimit": 10,
        "ResolverCountLimit": 100,
        "Tags": [
          {
            "Key": "graphqlapi:createdBy",
            "Value": "SAM"
          }
        ],
        "Visibility": "PRIVATE"
      },
      "Type": "AWS::AppSync::GraphQLApi"
    },
    "SuperCoolAPICloudWatchRole": {
      "Properties": {
        "AssumeRolePolicyDocument": {
          "Statement": [
            {
              "Action": [
                "sts:AssumeRole"
              ],
              "Effect": "Allow",
              "Principal": {
                "Service": [
                  "appsync.amazonaws.com"
                ]
              }
            }
          ],
          "Version": "2012-10-17"
        },
        "ManagedPolicyArns": [
          {
            "Fn::Sub": "arn:${AWS::Partition}:iam::aws:policy/service-role/AWSAppSyncPushToCloudWatchLogs"
          }
        ]
      },
      "Type": "AWS::IAM::Role"
    },
    "SuperCoolAPISchema": {
      "Properties": {
        "ApiId": {
          "Fn::GetAtt": [
            "SuperCoolAPI",
            "ApiId"
          ]
        },
        "Definition": "type Book {\n    bookName: String\n} \ntype Query { getBook(bookName: String): Book }\n"
      },
      "Type": "AWS::AppSync::GraphQLSchema"
    }
  }
}

{
    "AWSTemplateFormatVersion": "2010-09-09",
    "Description": "AWS CloudFormation Sample Template DynamoDB_Secondary_Indexes: Create a DynamoDB table with local and global secondary indexes. **WARNING** This template creates an Amazon DynamoDB table. You will be billed for the AWS resources used if you create a stack from this template.",
    "Metadata": {
        "License": "Apache-2.0"
    },
    "Parameters": {
        "ReadCapacityUnits": {
            "Description": "Provisioned read throughput",
            "Type": "Number",
            "Default": "5",
            "MinValue": "5",
            "MaxValue": "10000",
            "ConstraintDescription": "must be between 5 and 10000"
        },
        "WriteCapacityUnits": {
            "Description": "Provisioned write throughput",
            "Type": "Number",
            "Default": "10",
            "MinValue": "5",
            "MaxValue": "10000",
            "ConstraintDescription": "must be between 5 and 10000"
        }
    },
    "Resources": {
        "TableOfBooks": {
            "Type": "AWS::DynamoDB::Table",
            "Properties": {
                "AttributeDefinitions": [
                    {
                        "AttributeName": "Title",
                        "AttributeType": "S"
                    },
                    {
                        "AttributeName": "Category",
                        "AttributeType": "S"
                    },
                    {
                        "AttributeName": "Language",
                        "AttributeType": "S"
                    }
                ],
                "KeySchema": [
                    {
                        "AttributeName": "Category",
                        "KeyType": "HASH"
                    },
                    {
                        "AttributeName": "Title",
                        "KeyType": "RANGE"
                    }
                ],
                "ProvisionedThroughput": {
                    "ReadCapacityUnits": {
                        "Ref": "ReadCapacityUnits"
                    },
                    "WriteCapacityUnits": {
                        "Ref": "WriteCapacityUnits"
                    }
                },
                "LocalSecondaryIndexes": [
                    {
                        "IndexName": "LanguageIndex",
                        "KeySchema": [
                            {
                                "AttributeName": "Category",
                                "KeyType": "HASH"
                            },
                            {
                                "AttributeName": "Language",
                                "KeyType": "RANGE"
                            }
                        ],
                        "Projection": {
                            "ProjectionType": "KEYS_ONLY"
                        }
                    }
                ],
                "GlobalSecondaryIndexes": [
                    {
                        "IndexName": "TitleIndex",
                        "KeySchema": [
                            {
                                "AttributeName": "Title",
                                "KeyType": "HASH"
                            }
                        ],
                        "Projection": {
                            "ProjectionType": "KEYS_ONLY"
                        },
                        "ProvisionedThroughput": {
                            "ReadCapacityUnits": {
                                "Ref": "ReadCapacityUnits"
                            },
                            "WriteCapacityUnits": {
                                "Ref": "WriteCapacityUnits"
                            }
                        }
                    }
                ],
                "PointInTimeRecoverySpecification": {
                    "PointInTimeRecoveryEnabled": true
                }
            }
        }
    },
    "Outputs": {
        "TableName": {
            "Description": "Name of the newly created DynamoDB table",
            "Value": {
                "Ref": "TableOfBooks"
            }
        }
    }
}

